@ParameterizedTest
// max iterations
@CsvSource({ //
"10", //
"5", //
"1", //
"0", //
"-1" })
void testSafeDoWhileLoopThrowsOnExceedingMaxIterations(int maxIterations) {
    TestContext context = new TestContext();
    // infinite
    Predicate<TestContext> condition = ctx -> true;
    LoopGuard.LoopBody<TestContext> body = ctx -> ctx.iteration++;
    IllegalStateException exception = Assertions.assertThrows(IllegalStateException.class, () -> LoopGuard.runSafeDoWhileLoop(maxIterations, context, condition, body));
    Assertions.assertTrue(exception.getMessage().contains("Loop exceeded " + maxIterations));
}

