public void testLoanRepaymentPastDueAmountCalculations() {
    // given
    LocalDate businessDate = DateUtils.getBusinessLocalDate();
    Loan loanForProcessing = Mockito.mock(Loan.class);
    MonetaryCurrency loanCurrency = new MonetaryCurrency("CODE", 1, 1);
    // repayments
    // closed repayment
    LocalDate repayment1DueDate = businessDate.minusDays(5);
    LoanRepaymentScheduleInstallment repaymentInstallment_closed = new LoanRepaymentScheduleInstallment(loanForProcessing, 1, LocalDate.now(ZoneId.systemDefault()), repayment1DueDate, BigDecimal.valueOf(100.0), BigDecimal.valueOf(10.0), BigDecimal.valueOf(10.0), BigDecimal.valueOf(10.0), false, new HashSet<>(), BigDecimal.valueOf(0.0));
    repaymentInstallment_closed.updateObligationMet(true);
    // past due repayments
    LocalDate repayment2DueDate = businessDate.minusDays(4);
    LoanRepaymentScheduleInstallment repaymentInstallment_1 = new LoanRepaymentScheduleInstallment(loanForProcessing, 2, LocalDate.now(ZoneId.systemDefault()), repayment2DueDate, BigDecimal.valueOf(100.0), BigDecimal.valueOf(10.0), BigDecimal.valueOf(10.0), BigDecimal.valueOf(10.0), false, new HashSet<>(), BigDecimal.valueOf(0.0));
