        3).repaymentEvery(//
        1).repaymentFrequencyType(//
        1L).allowPartialPeriodInterestCalcualtion(//
        false).multiDisburseLoan(//
        false).disallowExpectedDisbursements(//
        null).allowApprovedDisbursedAmountsOverApplied(//
        null).overAppliedCalculationType(//
        null).overAppliedNumber(//
        null).installmentAmountInMultiplesOf(//
        null);
        //
        PostLoanProductsResponse loanProductResponse = loanProductHelper.createLoanProduct(product);
        PostLoansRequest applicationRequest = applyLoanRequest(clientId, loanProductResponse.getResourceId(), operationDate, 100.0, 3).interestRatePerPeriod(BigDecimal.valueOf(4.0));
        applicationRequest = applicationRequest.interestCalculationPeriodType(DAYS).transactionProcessingStrategyCode(LoanProductTestBuilder.ADVANCED_PAYMENT_ALLOCATION_STRATEGY);
        PostLoansResponse loanResponse = loanTransactionHelper.applyLoan(applicationRequest);
        createdLoanId.set(loanResponse.getLoanId());
        loanTransactionHelper.approveLoan(loanResponse.getLoanId(), new PostLoansLoanIdRequest().approvedLoanAmount(BigDecimal.valueOf(100.0)).dateFormat(DATETIME_PATTERN).approvedOnDate(operationDate).locale("en"));
        loanTransactionHelper.disburseLoan(loanResponse.getLoanId(), new PostLoansLoanIdRequest().actualDisbursementDate(operationDate).dateFormat(DATETIME_PATTERN).transactionAmount(BigDecimal.valueOf(100.0)).locale("en"));
        // After Disbursement we are expecting amount in Zero
        GetLoansLoanIdResponse loanDetails = loanTransactionHelper.getLoanDetails(loanResponse.getLoanId());
        assertEquals(BigDecimal.ZERO, loanDetails.getSummary().getTotalUnpaidPayableDueInterest().stripTrailingZeros());
        assertEquals(BigDecimal.ZERO, loanDetails.getSummary().getTotalUnpaidPayableNotDueInterest().stripTrailingZeros());
    });
    runAt("23 March 2025", () -> {
        executeInlineCOB(createdLoanId.get());
        GetLoansLoanIdResponse loanDetails = loanTransactionHelper.getLoanDetails(createdLoanId.get());
        // totalUnpaidPayableDueInterest → Total outstanding interest amount on all the periods that are before
        assertEquals(BigDecimal.valueOf(loanDetails.getSummary().getInterestCharged()).stripTrailingZeros(), loanDetails.getSummary().getTotalUnpaidPayableDueInterest().stripTrailingZeros());
        // Total outstanding interest amount on the current period, if the current period due date is after than the
        // current date
        assertEquals(BigDecimal.ZERO, loanDetails.getSummary().getTotalUnpaidPayableNotDueInterest().stripTrailingZeros());
    });
}

