    // Create datatable entry batch request
    final BatchRequest createDatatableEntryRequest = BatchHelper.createDatatableEntryRequest(loanId.toString(), datatableName, Arrays.asList(columnName1, columnName2));
    // Get datatable entries batch request
    final BatchRequest getDatatableEntriesRequest = BatchHelper.getDatatableByIdRequest(loanId, datatableName, null, createDatatableEntryRequest.getReference());
    final List<BatchRequest> batchRequestsDatatableEntries = Arrays.asList(createDatatableEntryRequest, getDatatableEntriesRequest);
    LOG.info("Batch Request : {}", BatchHelper.toJsonString(batchRequestsDatatableEntries));
    final List<BatchResponse> responseDatatableBatch = BatchHelper.postBatchRequestsWithEnclosingTransaction(this.requestSpec, this.responseSpec, BatchHelper.toJsonString(batchRequestsDatatableEntries));
    LOG.info("Batch Response : {}", new Gson().toJson(responseDatatableBatch));
