@Test
public void testClientTransactions() {
    PostClientsRequest createClientRequest = ClientHelper.defaultClientCreationRequest();
    String clientExternalId = UUID.randomUUID().toString();
    createClientRequest.setExternalId(clientExternalId);
    PostClientsResponse client = clientHelper.createClient(createClientRequest);
    Long clientId = client.getClientId();
    assertNotNull(clientId);
    final Integer chargeId = ChargesHelper.createCharges(requestSpec, responseSpec, ChargesHelper.getChargeSpecifiedDueDateJSON());
    Assertions.assertNotNull(chargeId);
    final Integer clientChargeId1 = ClientHelper.addChargesForClient(requestSpec, responseSpec, clientId.intValue(), ClientHelper.getSpecifiedDueDateChargesClientAsJSON(chargeId.toString(), "29 October 2011"));
    Assertions.assertNotNull(clientChargeId1);
    String transactionExternalId = UUID.randomUUID().toString();
    final String clientChargePaidTransactionId1 = ClientHelper.payChargesForClients(requestSpec, responseSpec, clientId.intValue(), clientChargeId1, ClientHelper.getPayChargeJSON("25 AUGUST 2015", "10"));
    assertNotNull(clientChargePaidTransactionId1);
    final Integer clientChargeId2 = ClientHelper.addChargesForClient(requestSpec, responseSpec, clientId.intValue(), ClientHelper.getSpecifiedDueDateChargesClientAsJSON(chargeId.toString(), "29 October 2011"));
    Assertions.assertNotNull(clientChargeId2);
    final String clientChargePaidTransactionExternalId = ClientHelper.payChargesForClientsTransactionExternalId(requestSpec, responseSpec, clientId.intValue(), clientChargeId2, ClientHelper.getPayChargeJSONWithExternalId("25 AUGUST 2015", "12", transactionExternalId));
    assertNotNull(clientChargePaidTransactionExternalId);
    GetClientsClientIdTransactionsResponse allClientTransactionsByExternalId = clientHelper.getAllClientTransactionsByExternalId(clientExternalId);
    assertEquals(2, allClientTransactionsByExternalId.getTotalFilteredRecords());
    GetClientsClientIdTransactionsTransactionIdResponse clientTransactionByExternalId = clientHelper.getClientTransactionByExternalId(clientExternalId, clientChargePaidTransactionId1);
    assertEquals(Integer.parseInt(clientChargePaidTransactionId1), clientTransactionByExternalId.getId());
    GetClientsClientIdTransactionsTransactionIdResponse clientTransactionByTransactionExternalId = clientHelper.getClientTransactionByTransactionExternalId(clientId, clientChargePaidTransactionExternalId);
    assertNotNull(clientTransactionByTransactionExternalId);
    assertEquals(BigDecimal.valueOf(12), clientTransactionByTransactionExternalId.getAmount().stripTrailingZeros());
    PostClientsClientIdTransactionsTransactionIdResponse undoTransactionResponse = clientHelper.undoClientTransactionByExternalId(clientExternalId, clientChargePaidTransactionId1);
    assertNotNull(undoTransactionResponse.getResourceId());
    PostClientsClientIdTransactionsTransactionIdResponse undoTransactionResponse2 = clientHelper.undoClientTransactionByTransactionExternalId(clientId, clientChargePaidTransactionExternalId);
    assertNotNull(undoTransactionResponse2.getResourceId());
}

