        assertTrue(expectedMaturityDate.isEqual(actualMaturityDate));
    } finally {
        globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_AUTO_GENERATED_EXTERNAL_ID, new PutGlobalConfigurationsRequest().enabled(false));
    }
}

