@Test
public void accrualIsCalculatedWhenTheLoanIsClosed() {
    try {
        globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_AUTO_GENERATED_EXTERNAL_ID, new PutGlobalConfigurationsRequest().enabled(true));
