public void testClientAddressCreationWorks() {
    // given
    globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_ADDRESS, new PutGlobalConfigurationsRequest().enabled(true));
    GlobalConfigurationPropertyData updatedAddressEnabledConfig = globalConfigurationHelper.getGlobalConfigurationByName(GlobalConfigurationConstants.ENABLE_ADDRESS);
    assertThat(updatedAddressEnabledConfig.getEnabled()).isTrue();
