@Test
public void clientChargeTest() {
    // Creates clientCharge
    final Integer chargeId = ChargesHelper.createCharges(this.requestSpec, this.responseSpec, ChargesHelper.getChargeSpecifiedDueDateJSON());
    Assertions.assertNotNull(chargeId);
    // creates client with activation date
    final Integer clientId = ClientHelper.createClient(this.requestSpec, this.responseSpec, "01 October 2011");
    Assertions.assertNotNull(clientId);
    /**
     * create a charge for loan and try to associate to client created in the above lines.it will be an invalid
     * scenario the reason is client is not allowed to have only client charge.
     */
    final Integer loanChargeId = ChargesHelper.createCharges(this.requestSpec, this.responseSpec, ChargesHelper.getLoanSpecifiedDueDateJSON());
    Assertions.assertNotNull(loanChargeId);
    ResponseSpecification responseLoanChargeFailure = new ResponseSpecBuilder().expectStatusCode(403).build();
    final Integer clientLoanChargeId = ClientHelper.addChargesForClient(this.requestSpec, responseLoanChargeFailure, clientId, ClientHelper.getSpecifiedDueDateChargesClientAsJSON(loanChargeId.toString(), "29 October 2011"));
    Assertions.assertNull(clientLoanChargeId);
    /**
     * associates a clientCharge to a client and pay client charge for 10 USD--success scenario
     */
    final Integer clientChargeId = ClientHelper.addChargesForClient(this.requestSpec, this.responseSpec, clientId, ClientHelper.getSpecifiedDueDateChargesClientAsJSON(chargeId.toString(), "29 October 2011"));
    Assertions.assertNotNull(clientChargeId);
    final String clientChargePaidTransactionId = ClientHelper.payChargesForClients(this.requestSpec, this.responseSpec, clientId, clientChargeId, ClientHelper.getPayChargeJSON("25 AUGUST 2015", "10"));
    Assertions.assertNotNull(clientChargePaidTransactionId);
    isValidOutstandingAmount(ClientHelper.getClientCharge(requestSpec, responseSpec, clientId.toString(), clientChargeId.toString()), (float) 190.0);
    /**
     * Revert the paid client charge transaction by passing the clientChargePaidTransactionId and ensure the same is
     * reverted.
     */
    final Integer undoTrxnId = ClientHelper.revertClientChargeTransaction(this.requestSpec, this.responseSpec, clientId.toString(), clientChargePaidTransactionId);
    Assertions.assertNotNull(undoTrxnId);
    isReversedTransaction(clientId.toString(), undoTrxnId.toString());
    /**
     * Now pay client charge for 20 USD and ensure the outstanding amount is updated properly
     */
    ResponseSpecification responseSpecFailure = new ResponseSpecBuilder().expectStatusCode(400).build();
    DateFormat dateFormat = new SimpleDateFormat("dd MMMM yyyy", Locale.US);
    dateFormat.setTimeZone(Utils.getTimeZoneOfTenant());
    Calendar today = Calendar.getInstance(Utils.getTimeZoneOfTenant());
    today.add(Calendar.DAY_OF_MONTH, 2);
    final String responseId_futureDate_failure = ClientHelper.payChargesForClients(this.requestSpec, responseSpecFailure, clientId, clientChargeId, ClientHelper.getPayChargeJSON(dateFormat.format(today.getTime()), "20"));
    Assertions.assertNull(responseId_futureDate_failure);
    // waived off the outstanding client charge
    final String waiveOffClientChargeTransactionId = ClientHelper.waiveChargesForClients(this.requestSpec, this.responseSpec, clientId, clientChargeId, ClientHelper.getWaiveChargeJSON("100", clientChargeId.toString()));
    Assertions.assertNotNull(waiveOffClientChargeTransactionId);
    /**
     * Revert the waived off client charge transaction by passing the waiveOffClientChargeTransactionId and ensured
     * the transaction is reversed.
     */
    final Integer undoWaiveTrxnId = ClientHelper.revertClientChargeTransaction(this.requestSpec, this.responseSpec, clientId.toString(), waiveOffClientChargeTransactionId);
    Assertions.assertNotNull(undoWaiveTrxnId);
    isReversedTransaction(clientId.toString(), undoWaiveTrxnId.toString());
    /**
     * pay client charge before client activation date and ensured its a failure test case
     */
    final String responseId_activationDate_failure = ClientHelper.payChargesForClients(this.requestSpec, responseSpecFailure, clientId, clientChargeId, ClientHelper.getPayChargeJSON("30 September 2011", "20"));
    Assertions.assertNull(responseId_activationDate_failure);
    /**
     * pay client charge more than outstanding amount amount and ensured its a failure test case
     */
    final String responseId_moreAmount_failure = ClientHelper.payChargesForClients(this.requestSpec, responseSpecFailure, clientId, clientChargeId, ClientHelper.getPayChargeJSON("25 AUGUST 2015", "300"));
    Assertions.assertNull(responseId_moreAmount_failure);
    /**
     * pay client charge for 10 USD and ensure outstanding amount is updated properly
     */
    final String chargePaid_responseId = ClientHelper.payChargesForClients(this.requestSpec, this.responseSpec, clientId, clientChargeId, ClientHelper.getPayChargeJSON("25 AUGUST 2015", "100"));
    Assertions.assertNotNull(chargePaid_responseId);
    isValidOutstandingAmount(ClientHelper.getClientCharge(requestSpec, responseSpec, clientId.toString(), clientChargeId.toString()), (float) 100.0);
}

