public void testApptableWithDatatableAdvancedQuery() {
    String datatable = createAndVerifyDatatable(SAVINGS_TRANSACTION_APP_TABLE_NAME, null, false);
    LocalDate today = Utils.getLocalDateOfTenant();
    String todayS = DateUtils.format(today, SAVINGS_DATE_FORMAT);
    LocalDate yesterday = today.minus(1, ChronoUnit.DAYS);
    String yesterdayS = DateUtils.format(yesterday, SAVINGS_DATE_FORMAT);
    try {
        globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_BUSINESS_DATE, new PutGlobalConfigurationsRequest().enabled(true));
        BusinessDateHelper.updateBusinessDate(requestSpec, responseSpec, BusinessDateType.BUSINESS_DATE, today);
        final Integer clientId = ClientHelper.createClient(requestSpec, responseSpec, yesterdayS);
        assertNotNull(clientId);
        final Integer savingsId = createSavingsAccountDailyPosting(clientId, yesterdayS);
        assertNotNull(savingsId);
        final Integer transactionIdD1 = (Integer) savingsAccountHelper.depositToSavingsAccount(savingsId, "100", yesterdayS, CommonConstants.RESPONSE_RESOURCE_ID);
        assertNotNull(transactionIdD1);
        BigDecimal decValue1 = new BigDecimal("1.111");
        createDatatableEntry(datatable, transactionIdD1, yesterday, true, 1, decValue1);
        final Integer transactionIdD2 = (Integer) savingsAccountHelper.depositToSavingsAccount(savingsId, "300", yesterdayS, CommonConstants.RESPONSE_RESOURCE_ID);
        assertNotNull(transactionIdD2);
        BigDecimal decValue2 = new BigDecimal("2.2");
        createDatatableEntry(datatable, transactionIdD2, yesterday, false, 2, decValue2);
        final Integer transactionIdW1 = (Integer) savingsAccountHelper.withdrawalFromSavingsAccount(savingsId, "100", todayS, CommonConstants.RESPONSE_RESOURCE_ID);
        assertNotNull(transactionIdW1);
        createDatatableEntry(datatable, transactionIdW1, today, true, 3, new BigDecimal("3"));
        String yesterdayIsoS = DateUtils.format(yesterday, DateUtils.DEFAULT_DATE_FORMAT);
        String todayIsoS = DateUtils.format(today, DateUtils.DEFAULT_DATE_FORMAT);
        AdvancedQueryData baseQuery = new AdvancedQueryData().resultColumns(List.of(COLUMN_ID, COLUMN_SUBMITTED_DATE)).addColumnFiltersItem(new ColumnFilterData().column(COLUMN_AMOUNT).addFiltersItem(new FilterData().operator(GT).values(List.of("100")))).addColumnFiltersItem(new ColumnFilterData().column(COLUMN_SUBMITTED_DATE).addFiltersItem(new FilterData().operator(BTW).values(List.of(todayIsoS, todayIsoS))));
        AdvancedQueryData dataQuery = new AdvancedQueryData().resultColumns(List.of(COLUMN_TRANSACTION_ID, COLUMN_STRING, COLUMN_TEXT, COLUMN_DATE, COLUMN_BOOLEAN, COLUMN_INTEGER, COLUMN_DECIMAL)).addColumnFiltersItem(new ColumnFilterData().column(COLUMN_TEXT).addFiltersItem(new FilterData().operator(IN).values(List.of(transactionIdD1.toString(), transactionIdD2.toString())))).addColumnFiltersItem(new ColumnFilterData().column(COLUMN_DATE).addFiltersItem(new FilterData().operator(BTW).values(List.of(yesterdayIsoS, yesterdayIsoS))));
        AdvancedQueryRequest queryRequest = new AdvancedQueryRequest().baseQuery(baseQuery).datatableQueries(List.of(new TableQueryData().table(datatable).query(dataQuery)));
        PagedLocalRequestAdvancedQueryRequest pagedRequest = new PagedLocalRequestAdvancedQueryRequest().page(0).size(2).addSortsItem(new SortOrder().property(COLUMN_SUBMITTED_DATE).direction(SortOrder.DirectionEnum.DESC)).addSortsItem(new SortOrder().property(COLUMN_ID).direction(SortOrder.DirectionEnum.DESC)).request(queryRequest);
