        //
        verifyBusinessEvents(new LoanAdjustTransactionBusinessEvent("LoanAdjustTransactionBusinessEvent", "05 February 2025", "loanTransactionType.chargeOff", //
        "2025-02-04"), new LoanAdjustTransactionBusinessEvent("LoanAdjustTransactionBusinessEvent", "05 February 2025", "loanTransactionType.repayment", //
        "2025-02-01"), new LoanTransactionBusinessEvent("LoanAccrualTransactionCreatedBusinessEvent", "05 February 2025", 0.15, 0.0, 0.0, 0.15, 0.0, //
        0.0));
    });
}

