     */
    Account liabilityTransferAccount = accountHelper.createLiabilityAccount();
    Account assetTransferAccount = accountHelper.createAssetAccount();
    Assertions.assertNotNull(assetTransferAccount);
    Assertions.assertNotNull(liabilityTransferAccount);
    /**
     * Create A Financial Activity to Account Mapping *
     */
    Integer financialActivityAccountId = (Integer) financialActivityAccountHelper.createFinancialActivityAccount(LIABILITY_TRANSFER_FINANCIAL_ACTIVITY_ID, liabilityTransferAccount.getAccountID(), responseSpec, CommonConstants.RESPONSE_RESOURCE_ID);
    Assertions.assertNotNull(financialActivityAccountId);
    /**
     * Fetch Created Financial Activity to Account Mapping and validate created values
     */
    assertFinancialActivityAccountCreation(financialActivityAccountId, LIABILITY_TRANSFER_FINANCIAL_ACTIVITY_ID, liabilityTransferAccount);
    /**
     * Update Existing Financial Activity to Account Mapping and assert changes
     */
    Account newLiabilityTransferAccount = accountHelper.createLiabilityAccount();
    Assertions.assertNotNull(newLiabilityTransferAccount);
    HashMap changes = (HashMap) financialActivityAccountHelper.updateFinancialActivityAccount(financialActivityAccountId, LIABILITY_TRANSFER_FINANCIAL_ACTIVITY_ID, newLiabilityTransferAccount.getAccountID(), responseSpec, CommonConstants.RESPONSE_CHANGES);
