@Test
public void shouldUpdateStepOrder() {
    ResponseSpecification updateResponseSpec = new ResponseSpecBuilder().expectStatusCode(204).build();
    JobBusinessStepConfigData originalStepConfig = IdempotencyHelper.getConfiguredBusinessStepsByJobName(requestSpec, responseSpec, LOAN_JOB_NAME);
    String idempotencyKeyHeader = UUID.randomUUID().toString();
    List<BusinessStep> requestBody = new ArrayList<>();
    requestBody.add(getBusinessSteps(1L, APPLY_CHARGE_TO_OVERDUE_LOANS));
    Response response = IdempotencyHelper.updateBusinessStepOrder(requestSpec, updateResponseSpec, LOAN_JOB_NAME, IdempotencyHelper.toJsonString(requestBody), idempotencyKeyHeader);
    Response responseSecond = IdempotencyHelper.updateBusinessStepOrder(requestSpec, updateResponseSpec, LOAN_JOB_NAME, IdempotencyHelper.toJsonString(requestBody), idempotencyKeyHeader);
    assertEquals(response.getBody().asString(), responseSecond.getBody().asString());
    assertNull(response.header(AbstractIdempotentCommandException.IDEMPOTENT_CACHE_HEADER));
    assertNotNull(responseSecond.header(AbstractIdempotentCommandException.IDEMPOTENT_CACHE_HEADER));
    idempotencyKeyHeader = UUID.randomUUID().toString();
    JobBusinessStepConfigData newStepConfig = IdempotencyHelper.getConfiguredBusinessStepsByJobName(requestSpec, responseSpec, LOAN_JOB_NAME);
    BusinessStep applyChargeStep = newStepConfig.getBusinessSteps().stream().filter(businessStep -> APPLY_CHARGE_TO_OVERDUE_LOANS.equals(businessStep.getStepName())).findFirst().get();
    assertEquals(1, newStepConfig.getBusinessSteps().size());
    assertEquals(1L, applyChargeStep.getOrder());
    requestBody.add(getBusinessSteps(2L, LOAN_DELINQUENCY_CLASSIFICATION));
    Response update = IdempotencyHelper.updateBusinessStepOrder(requestSpec, updateResponseSpec, LOAN_JOB_NAME, IdempotencyHelper.toJsonString(requestBody), idempotencyKeyHeader);
    Response updateSecond = IdempotencyHelper.updateBusinessStepOrder(requestSpec, updateResponseSpec, LOAN_JOB_NAME, IdempotencyHelper.toJsonString(requestBody), idempotencyKeyHeader);
    assertNull(update.header(AbstractIdempotentCommandException.IDEMPOTENT_CACHE_HEADER));
    assertNotNull(updateSecond.header(AbstractIdempotentCommandException.IDEMPOTENT_CACHE_HEADER));
    assertEquals(update.getBody().asString(), updateSecond.getBody().asString());
    newStepConfig = IdempotencyHelper.getConfiguredBusinessStepsByJobName(requestSpec, responseSpec, LOAN_JOB_NAME);
    applyChargeStep = newStepConfig.getBusinessSteps().stream().filter(businessStep -> APPLY_CHARGE_TO_OVERDUE_LOANS.equals(businessStep.getStepName())).findFirst().get();
    BusinessStep loanDelinquencyStep = newStepConfig.getBusinessSteps().stream().filter(businessStep -> LOAN_DELINQUENCY_CLASSIFICATION.equals(businessStep.getStepName())).findFirst().get();
    assertEquals(2, newStepConfig.getBusinessSteps().size());
    assertEquals(1L, applyChargeStep.getOrder());
    assertEquals(2L, loanDelinquencyStep.getOrder());
    requestBody.remove(1);
    idempotencyKeyHeader = UUID.randomUUID().toString();
    update = IdempotencyHelper.updateBusinessStepOrder(requestSpec, updateResponseSpec, LOAN_JOB_NAME, IdempotencyHelper.toJsonString(requestBody), idempotencyKeyHeader);
    updateSecond = IdempotencyHelper.updateBusinessStepOrder(requestSpec, updateResponseSpec, LOAN_JOB_NAME, IdempotencyHelper.toJsonString(requestBody), idempotencyKeyHeader);
    assertNull(update.header(AbstractIdempotentCommandException.IDEMPOTENT_CACHE_HEADER));
    assertNotNull(updateSecond.header(AbstractIdempotentCommandException.IDEMPOTENT_CACHE_HEADER));
    assertEquals(update.getBody().asString(), updateSecond.getBody().asString());
    newStepConfig = IdempotencyHelper.getConfiguredBusinessStepsByJobName(requestSpec, responseSpec, LOAN_JOB_NAME);
    applyChargeStep = newStepConfig.getBusinessSteps().stream().filter(businessStep -> APPLY_CHARGE_TO_OVERDUE_LOANS.equals(businessStep.getStepName())).findFirst().get();
    assertEquals(1, newStepConfig.getBusinessSteps().size());
    assertEquals(1L, applyChargeStep.getOrder());
    idempotencyKeyHeader = UUID.randomUUID().toString();
    update = IdempotencyHelper.updateBusinessStepOrder(requestSpec, updateResponseSpec, LOAN_JOB_NAME, IdempotencyHelper.toJsonString(originalStepConfig.getBusinessSteps()), idempotencyKeyHeader);
    updateSecond = IdempotencyHelper.updateBusinessStepOrder(requestSpec, updateResponseSpec, LOAN_JOB_NAME, IdempotencyHelper.toJsonString(originalStepConfig.getBusinessSteps()), idempotencyKeyHeader);
    assertNull(update.header(AbstractIdempotentCommandException.IDEMPOTENT_CACHE_HEADER));
    assertNotNull(updateSecond.header(AbstractIdempotentCommandException.IDEMPOTENT_CACHE_HEADER));
    assertEquals(update.getBody().asString(), updateSecond.getBody().asString());
}

