        loanId, //
        installment(1250.0, null, "01 January 2023"), // 120 days delinquent -> range4
        installment(312.0, false, "31 January 2023"), // 90 days delinquent -> range4
        installment(312.0, false, "02 March 2023"), // 60 days delinquent -> range3
        installment(312.0, false, "01 April 2023"), // 30 days delinquent -> range2
