        // make a repayment on 3rd od Sept
        updateBusinessDate("3 September 2022");
        final PostLoansLoanIdTransactionsResponse repaymentTransaction = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("3 September 2022").locale("en").transactionAmount(100.0));
        // apply charges on 4th of Sept backdated to 2nd of Sept 2022
        updateBusinessDate("4 September 2022");
        Integer feeCharge = ChargesHelper.createCharges(requestSpec, responseSpec, ChargesHelper.getLoanSpecifiedDueDateJSON(ChargesHelper.CHARGE_CALCULATION_TYPE_FLAT, "10", false));
        LocalDate targetDate = LocalDate.of(2022, 9, 2);
