        Integer feeLoanChargeId = loanTransactionHelper.addChargesForLoan(loanId, LoanTransactionHelper.getSpecifiedDueDateChargesForLoanAsJSON(String.valueOf(feeCharge), feeCharge1AddedDate, "10"));
        // apply penalty
        Integer penalty = ChargesHelper.createCharges(requestSpec, responseSpec, ChargesHelper.getLoanSpecifiedDueDateJSON(ChargesHelper.CHARGE_CALCULATION_TYPE_FLAT, "20", true));
        final String penaltyCharge1AddedDate = DATE_FORMATTER.format(targetDate);
        Integer penalty1LoanChargeId = this.loanTransactionHelper.addChargesForLoan(loanId, LoanTransactionHelper.getSpecifiedDueDateChargesForLoanAsJSON(String.valueOf(penalty), penaltyCharge1AddedDate, "20"));
        // make a full repayment of 10th of September
        updateBusinessDate("10 September 2022");
        PostLoansLoanIdTransactionsResponse fullRepayment = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("10 September 2022").locale("en").transactionAmount(930.0));
        GetLoansLoanIdResponse loanDetails = this.loanTransactionHelper.getLoanDetails((long) loanId);
        assertNotNull(loanDetails.getRepaymentSchedule());
        assertNotNull(loanDetails.getRepaymentSchedule().getPeriods());
        assertEquals(2, loanDetails.getRepaymentSchedule().getPeriods().size());
        assertEquals(0.0, loanDetails.getRepaymentSchedule().getPeriods().get(1).getPenaltyChargesOutstanding());
        assertEquals(0.0, loanDetails.getRepaymentSchedule().getPeriods().get(1).getFeeChargesOutstanding());
        assertEquals(0.0, loanDetails.getRepaymentSchedule().getPeriods().get(1).getPrincipalOutstanding());
        assertEquals(0.0, loanDetails.getRepaymentSchedule().getPeriods().get(1).getTotalOutstandingForPeriod());
        // adding an extra charge after maturity
        updateBusinessDate("11 October 2022");
        Integer snoozeFee = ChargesHelper.createCharges(requestSpec, responseSpec, ChargesHelper.getLoanSpecifiedDueDateJSON(ChargesHelper.CHARGE_CALCULATION_TYPE_FLAT, "30.0", false));
        loanTransactionHelper.addChargesForLoan(loanId, LoanTransactionHelper.getSpecifiedDueDateChargesForLoanAsJSON(String.valueOf(snoozeFee), "11 October 2022", "30.0"));
        loanDetails = this.loanTransactionHelper.getLoanDetails((long) loanId);
        assertNotNull(loanDetails.getRepaymentSchedule());
        assertNotNull(loanDetails.getRepaymentSchedule().getPeriods());
        // extra instalment is created
        assertEquals(3, loanDetails.getRepaymentSchedule().getPeriods().size());
        // not repayed
        assertNull(loanDetails.getRepaymentSchedule().getPeriods().get(2).getObligationsMetOnDate());
    });
