@Test
public void loanCreditRefundPayoutGetCreatedWithChargebackTest() {
    // Loan ExternalId
    String loanExternalIdStr = UUID.randomUUID().toString();
    // Delinquency Bucket
    final Integer delinquencyBucketId = DelinquencyBucketsHelper.createDelinquencyBucket(requestSpec, responseSpec);
    final DelinquencyBucketData delinquencyBucket = DelinquencyBucketsHelper.getDelinquencyBucket(requestSpec, responseSpec, delinquencyBucketId);
    // Client and Loan account creation
    final Integer clientId = clientHelper.createClient(ClientHelper.defaultClientCreationRequest()).getClientId().intValue();
    final GetLoanProductsProductIdResponse getLoanProductsProductResponse = createLoanProduct(loanTransactionHelper, delinquencyBucketId);
    assertNotNull(getLoanProductsProductResponse);
    final Integer loanId = createLoanAccount(clientId, getLoanProductsProductResponse.getId(), loanExternalIdStr);
    // make Repayment with full amount, Loan balance becomes zero, Loan closes
    final PostLoansLoanIdTransactionsResponse repaymentTransaction_1 = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("5 September 2022").locale("en").transactionAmount(1000.0));
    // Chargeback full repayment amount to add to principal balance
    PostLoansLoanIdTransactionsResponse chargebackResponse = loanTransactionHelper.chargebackLoanTransaction(loanExternalIdStr, repaymentTransaction_1.getResourceId(), new PostLoansLoanIdTransactionsTransactionIdRequest().locale("en").transactionAmount(1000.0).paymentTypeId(1L));
    GetLoansLoanIdTransactionsTransactionIdResponse chargebackTransactionResponse = loanTransactionHelper.getLoanTransactionDetails(chargebackResponse.getLoanId(), chargebackResponse.getResourceId());
    assertEquals(1L, chargebackTransactionResponse.getPaymentDetailData().getPaymentType().getId());
    // Verify Goodwill Credit can be created with full amount
    final PostLoansLoanIdTransactionsResponse goodwillCredit_1 = loanTransactionHelper.makeGoodwillCredit((long) loanId, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("8 September 2022").locale("en").transactionAmount(1000.0));
    assertNotNull(goodwillCredit_1);
    assertEquals(goodwillCredit_1.getLoanId(), (long) loanId);
    // Verify Goodwill Credit can be created after balance is zero again
    final PostLoansLoanIdTransactionsResponse goodwillCredit_2 = loanTransactionHelper.makeGoodwillCredit((long) loanId, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("9 September 2022").locale("en").transactionAmount(10.0));
    assertNotNull(goodwillCredit_2);
    assertEquals(goodwillCredit_2.getLoanId(), (long) loanId);
    // Verify Payout refund can be created after balance is zero again
    final PostLoansLoanIdTransactionsResponse payoutRefund_1 = loanTransactionHelper.makePayoutRefund((long) loanId, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("9 September 2022").locale("en").transactionAmount(10.0));
    assertNotNull(payoutRefund_1);
    assertEquals(payoutRefund_1.getLoanId(), (long) loanId);
    // Verify Merchant refund can be created after balance is zero again
    final PostLoansLoanIdTransactionsResponse merchantIssuedRefund_1 = loanTransactionHelper.makeMerchantIssuedRefund((long) loanId, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("10 September 2022").locale("en").transactionAmount(10.0));
    assertNotNull(merchantIssuedRefund_1);
    assertEquals(merchantIssuedRefund_1.getLoanId(), (long) loanId);
}

