@Test
public void testMarkLoanAsFraud() {
    runAt(operationDate, () -> {
        final Long clientId = clientHelper.createClient(ClientHelper.defaultClientCreationRequest()).getClientId();
        PostLoanProductsRequest loanProductsRequest = createOnePeriod30DaysLongNoInterestPeriodicAccrualProduct();
        PostLoanProductsResponse loanProductResponse = loanProductHelper.createLoanProduct(loanProductsRequest);
        PostLoansResponse postLoansResponse = loanTransactionHelper.applyLoan(applyLoanRequest(clientId, loanProductResponse.getResourceId(), operationDate, AMOUNT, 1));
        Integer loanId = postLoansResponse.getLoanId().intValue();
        GetLoansLoanIdResponse getLoansLoanIdResponse = loanTransactionHelper.getLoan(requestSpec, responseSpec, loanId);
        assertNotNull(getLoansLoanIdResponse);
        // Default values Not Null and False
        assertNotNull(getLoansLoanIdResponse.getFraud());
        assertEquals(Boolean.FALSE, getLoansLoanIdResponse.getFraud());
        String payload = loanTransactionHelper.getLoanFraudPayloadAsJSON("fraud", "true");
        PutLoansLoanIdResponse putLoansLoanIdResponse = loanTransactionHelper.modifyLoanCommand(loanId, COMMAND, payload, responseSpec);
        assertNotNull(putLoansLoanIdResponse);
        getLoansLoanIdResponse = loanTransactionHelper.getLoan(requestSpec, responseSpec, loanId);
        assertNotNull(getLoansLoanIdResponse);
        assertNotNull(getLoansLoanIdResponse.getFraud());
        assertEquals(Boolean.TRUE, getLoansLoanIdResponse.getFraud());
        String statusCode = getLoansLoanIdResponse.getStatus().getCode();
        log.info("Loan with Id {} is with Status {}", getLoansLoanIdResponse.getId(), statusCode);
        payload = loanTransactionHelper.getLoanFraudPayloadAsJSON("fraud", "false");
        putLoansLoanIdResponse = loanTransactionHelper.modifyLoanCommand(loanId, COMMAND, payload, responseSpec);
        assertNotNull(putLoansLoanIdResponse);
        getLoansLoanIdResponse = loanTransactionHelper.getLoan(requestSpec, responseSpec, loanId);
        assertNotNull(getLoansLoanIdResponse);
        assertNotNull(getLoansLoanIdResponse.getFraud());
        assertEquals(Boolean.FALSE, getLoansLoanIdResponse.getFraud());
        statusCode = getLoansLoanIdResponse.getStatus().getCode();
        log.info("Loan with Id {} is with Status {}", getLoansLoanIdResponse.getId(), statusCode);
        // Approve the Loan active
        PostLoansLoanIdResponse approvedLoanResult = loanTransactionHelper.approveLoan(postLoansResponse.getResourceId(), approveLoanRequest(AMOUNT, operationDate));
        assertNotNull(approvedLoanResult);
        payload = loanTransactionHelper.getLoanFraudPayloadAsJSON("fraud", "true");
        putLoansLoanIdResponse = loanTransactionHelper.modifyLoanCommand(loanId, COMMAND, payload, responseSpec);
        assertNotNull(putLoansLoanIdResponse);
        getLoansLoanIdResponse = loanTransactionHelper.getLoan(requestSpec, responseSpec, loanId);
        assertNotNull(getLoansLoanIdResponse);
        assertNotNull(getLoansLoanIdResponse.getFraud());
        assertEquals(Boolean.TRUE, getLoansLoanIdResponse.getFraud());
        statusCode = getLoansLoanIdResponse.getStatus().getCode();
        log.info("Loan with Id {} is with Status {}", getLoansLoanIdResponse.getId(), statusCode);
        payload = loanTransactionHelper.getLoanFraudPayloadAsJSON("fraud", "false");
        putLoansLoanIdResponse = loanTransactionHelper.modifyLoanCommand(loanId, COMMAND, payload, responseSpec);
        assertNotNull(putLoansLoanIdResponse);
        // Default values Not Null and False
        getLoansLoanIdResponse = loanTransactionHelper.getLoan(requestSpec, responseSpec, loanId);
        assertNotNull(getLoansLoanIdResponse);
        assertNotNull(getLoansLoanIdResponse.getFraud());
        assertEquals(Boolean.FALSE, getLoansLoanIdResponse.getFraud());
        statusCode = getLoansLoanIdResponse.getStatus().getCode();
        log.info("Loan with Id {} is with Status {}", getLoansLoanIdResponse.getId(), statusCode);
        disburseLoan(loanId.longValue(), BigDecimal.valueOf(AMOUNT), operationDate);
        // Mark On the Fraud
        payload = loanTransactionHelper.getLoanFraudPayloadAsJSON("fraud", "true");
        putLoansLoanIdResponse = loanTransactionHelper.modifyLoanCommand(loanId, COMMAND, payload, responseSpec);
        assertNotNull(putLoansLoanIdResponse);
        getLoansLoanIdResponse = loanTransactionHelper.getLoan(requestSpec, responseSpec, loanId);
        assertNotNull(getLoansLoanIdResponse);
        assertNotNull(getLoansLoanIdResponse.getFraud());
        assertEquals(Boolean.TRUE, getLoansLoanIdResponse.getFraud());
        // Mark Off the Fraud
        payload = loanTransactionHelper.getLoanFraudPayloadAsJSON("fraud", "false");
        putLoansLoanIdResponse = loanTransactionHelper.modifyLoanCommand(loanId, COMMAND, payload, this.responseSpec);
        assertNotNull(putLoansLoanIdResponse);
        getLoansLoanIdResponse = loanTransactionHelper.getLoan(requestSpec, responseSpec, loanId);
        assertNotNull(getLoansLoanIdResponse);
        assertNotNull(getLoansLoanIdResponse.getFraud());
        assertEquals(Boolean.FALSE, getLoansLoanIdResponse.getFraud());
        payload = loanTransactionHelper.getLoanFraudPayloadAsJSON("fraud", "true");
        putLoansLoanIdResponse = loanTransactionHelper.modifyLoanCommand(loanId, COMMAND, payload, responseSpec);
        assertNotNull(putLoansLoanIdResponse);
        getLoansLoanIdResponse = loanTransactionHelper.getLoan(requestSpec, responseSpec, loanId);
        assertNotNull(getLoansLoanIdResponse);
        assertNotNull(getLoansLoanIdResponse.getFraud());
        assertEquals(Boolean.TRUE, getLoansLoanIdResponse.getFraud());
        statusCode = getLoansLoanIdResponse.getStatus().getCode();
        log.info("Loan with Id {} is with Status {}", getLoansLoanIdResponse.getId(), statusCode);
        undoDisbursement(loanId);
        getLoansLoanIdResponse = loanTransactionHelper.getLoan(requestSpec, responseSpec, loanId);
        assertNotNull(getLoansLoanIdResponse);
        assertNotNull(getLoansLoanIdResponse.getFraud());
        assertEquals(Boolean.TRUE, getLoansLoanIdResponse.getFraud());
        statusCode = getLoansLoanIdResponse.getStatus().getCode();
        log.info("Loan with Id {} is with Status {}", getLoansLoanIdResponse.getId(), statusCode);
    });
}

@Test
public void loanOverpaidDateStatusTest() {
    // Set business date
    try {
        final LocalDate todaysDate = Utils.getLocalDateOfTenant();
        globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_BUSINESS_DATE, new PutGlobalConfigurationsRequest().enabled(true));
        BusinessDateHelper.updateBusinessDate(requestSpec, responseSpec, BusinessDateType.BUSINESS_DATE, todaysDate);
        // Loan ExternalId
        String loanExternalIdStr = UUID.randomUUID().toString();
        // Delinquency Bucket
        final Integer delinquencyBucketId = DelinquencyBucketsHelper.createDelinquencyBucket(requestSpec, responseSpec);
        final DelinquencyBucketData delinquencyBucket = DelinquencyBucketsHelper.getDelinquencyBucket(requestSpec, responseSpec, delinquencyBucketId);
        // Client and Loan account creation
        final Integer clientId = clientHelper.createClient(ClientHelper.defaultClientCreationRequest()).getClientId().intValue();
        final GetLoanProductsProductIdResponse getLoanProductsProductResponse = createLoanProduct(loanTransactionHelper, delinquencyBucketId);
        assertNotNull(getLoanProductsProductResponse);
        final Integer loanId = createLoanAccount(clientId, getLoanProductsProductResponse.getId(), loanExternalIdStr);
        // make Repayments
        final PostLoansLoanIdTransactionsResponse repaymentTransaction_1 = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("5 September 2022").locale("en").transactionAmount(200.0));
        final PostLoansLoanIdTransactionsResponse repaymentTransaction_2 = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("6 September 2022").locale("en").transactionAmount(200.0));
        final PostLoansLoanIdTransactionsResponse repaymentTransaction_3 = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("7 September 2022").locale("en").transactionAmount(500.0));
        // make repayment to make loan overpaid
        final PostLoansLoanIdTransactionsResponse repaymentTransaction_4 = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("9 September 2022").locale("en").transactionAmount(200.0));
        // check loan overpaid date is not null and is set as Business date and loan status
        GetLoansLoanIdResponse loanDetailsOverpaid = loanTransactionHelper.getLoanDetails((long) loanId);
        assertTrue(loanDetailsOverpaid.getStatus().getOverpaid());
        assertNotNull(loanDetailsOverpaid.getOverpaidOnDate());
        assertEquals(loanDetailsOverpaid.getOverpaidOnDate(), LocalDate.of(2022, 9, 9));
        // reverse repayment to make loan not overpaid and overpaid date is reset
        loanTransactionHelper.reverseRepayment(loanId, repaymentTransaction_4.getResourceId().intValue(), "10 September 2022");
        GetLoansLoanIdResponse loanDetailsNotOverpaidAfterReversal = loanTransactionHelper.getLoanDetails((long) loanId);
        assertFalse(loanDetailsNotOverpaidAfterReversal.getStatus().getOverpaid());
        assertNull(loanDetailsNotOverpaidAfterReversal.getOverpaidOnDate());
        // make repayment to make loan overpaid again
        final PostLoansLoanIdTransactionsResponse repaymentTransaction_5 = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("11 September 2022").locale("en").transactionAmount(200.0));
        // check loan overpaid date is not null and is set as Business date and loan status
