    @SuppressWarnings("unchecked")
    List<HashMap> disbursalError = (List<HashMap>) this.loanTransactionHelper.disburseLoanWithNetDisbursalAmount(disbursalDate, loanID, this.responseForbiddenError, JsonPath.from(loanDetails).get("netDisbursalAmount").toString());
