@Test
public void testInterestRateChangeForProgressiveLoan() {
    PostClientsResponse client = clientHelper.createClient(ClientHelper.defaultClientCreationRequest());
    final Account assetAccount = accountHelper.createAssetAccount();
    final Account incomeAccount = accountHelper.createIncomeAccount();
    final Account expenseAccount = accountHelper.createExpenseAccount();
    final Account overpaymentAccount = accountHelper.createLiabilityAccount();
    Integer commonLoanProductId = createLoanProduct("500", "15", "4", true, "25", true, LoanScheduleType.PROGRESSIVE, LoanScheduleProcessingType.HORIZONTAL, assetAccount, incomeAccount, expenseAccount, overpaymentAccount);
    AtomicReference<PostCreateRescheduleLoansResponse> rescheduleResponse = new AtomicReference<>();
    AtomicReference<PostLoansResponse> loanResponse = new AtomicReference<>();
    // Do not allow interest rate change on not active loan
    // Do not allow interest rate change twice on the same day
    runAt("15 February 2023", () -> {
        loanResponse.set(applyForLoanApplication(client.getClientId(), commonLoanProductId, BigDecimal.valueOf(500.0), 45, 15, 3, BigDecimal.ZERO, "01 January 2023", "01 January 2023"));
        loanTransactionHelper.approveLoan(loanResponse.get().getLoanId(), new PostLoansLoanIdRequest().approvedLoanAmount(BigDecimal.valueOf(500)).dateFormat(DATETIME_PATTERN).approvedOnDate("01 January 2023").locale("en"));
        CallFailedRuntimeException exception = assertThrows(CallFailedRuntimeException.class, () -> loanRescheduleRequestHelper.createLoanRescheduleRequest(new PostCreateRescheduleLoansRequest().loanId(loanResponse.get().getLoanId()).dateFormat(DATETIME_PATTERN).locale("en").submittedOnDate("15 February 2023").newInterestRate(BigDecimal.ONE).rescheduleReasonId(1L).rescheduleFromDate("16 February 2023")));
        assertEquals(400, exception.getResponse().code());
        assertTrue(exception.getMessage().contains("loan.is.not.active"));
        loanTransactionHelper.disburseLoan(loanResponse.get().getLoanId(), new PostLoansLoanIdRequest().actualDisbursementDate("15 February 2023").dateFormat(DATETIME_PATTERN).transactionAmount(BigDecimal.valueOf(500.00)).locale("en"));
        exception = assertThrows(CallFailedRuntimeException.class, () -> loanRescheduleRequestHelper.createLoanRescheduleRequest(new PostCreateRescheduleLoansRequest().loanId(loanResponse.get().getLoanId()).dateFormat(DATETIME_PATTERN).locale("en").submittedOnDate("15 February 2023").newInterestRate(BigDecimal.ONE).rescheduleReasonId(1L).rescheduleFromDate("15 February 2023")));
        assertEquals(403, exception.getResponse().code());
        assertTrue(exception.getMessage().contains("loan.reschedule.interest.rate.change.reschedule.from.date.should.be.in.future"));
        rescheduleResponse.set(loanRescheduleRequestHelper.createLoanRescheduleRequest(new PostCreateRescheduleLoansRequest().loanId(loanResponse.get().getLoanId()).dateFormat(DATETIME_PATTERN).locale("en").submittedOnDate("15 February 2023").newInterestRate(BigDecimal.ONE).rescheduleReasonId(1L).rescheduleFromDate("16 February 2023")));
        exception = assertThrows(CallFailedRuntimeException.class, () -> loanRescheduleRequestHelper.createLoanRescheduleRequest(new PostCreateRescheduleLoansRequest().loanId(loanResponse.get().getLoanId()).dateFormat(DATETIME_PATTERN).locale("en").submittedOnDate("15 February 2023").newInterestRate(BigDecimal.ONE).rescheduleReasonId(1L).rescheduleFromDate("16 February 2023")));
        assertEquals(403, exception.getResponse().code());
        assertTrue(exception.getMessage().contains("loan.reschedule.interest.rate.change.already.exists"));
    });
    // Do not allow approve an interest rate change if the reschedule from date is not in the future
    // Do not allow create interest rate change if a previous interest rate change got already approved for that
    // date
    runAt("16 February 2023", () -> {
        CallFailedRuntimeException exception = assertThrows(CallFailedRuntimeException.class, () -> loanRescheduleRequestHelper.approveLoanRescheduleRequest(rescheduleResponse.get().getResourceId(), new PostUpdateRescheduleLoansRequest().approvedOnDate("16 February 2024").locale("en").dateFormat(DATETIME_PATTERN)));
        assertEquals(403, exception.getResponse().code());
        assertTrue(exception.getMessage().contains("loan.reschedule.interest.rate.change.reschedule.from.date.should.be.in.future"));
        PostCreateRescheduleLoansResponse rescheduleLoansResponse = loanRescheduleRequestHelper.createLoanRescheduleRequest(new PostCreateRescheduleLoansRequest().loanId(loanResponse.get().getLoanId()).dateFormat(DATETIME_PATTERN).locale("en").submittedOnDate("17 February 2023").newInterestRate(BigDecimal.ONE).rescheduleReasonId(1L).rescheduleFromDate("17 February 2023"));
        loanRescheduleRequestHelper.approveLoanRescheduleRequest(rescheduleLoansResponse.getResourceId(), new PostUpdateRescheduleLoansRequest().approvedOnDate("17 February 2024").locale("en").dateFormat(DATETIME_PATTERN));
        exception = assertThrows(CallFailedRuntimeException.class, () -> loanRescheduleRequestHelper.createLoanRescheduleRequest(new PostCreateRescheduleLoansRequest().loanId(rescheduleLoansResponse.getLoanId()).dateFormat(DATETIME_PATTERN).locale("en").submittedOnDate("17 February 2023").newInterestRate(BigDecimal.ONE).rescheduleReasonId(1L).rescheduleFromDate("17 February 2023")));
        assertEquals(403, exception.getResponse().code());
        assertTrue(exception.getMessage().contains("loan.reschedule.interest.rate.change.already.exists"));
    });
    // Allow new interest rate change if the previous got rejected
    runAt("17 February 2023", () -> {
        PostCreateRescheduleLoansResponse rescheduleLoansResponse = loanRescheduleRequestHelper.createLoanRescheduleRequest(new PostCreateRescheduleLoansRequest().loanId(loanResponse.get().getLoanId()).dateFormat(DATETIME_PATTERN).locale("en").submittedOnDate("18 February 2023").newInterestRate(BigDecimal.ONE).rescheduleReasonId(1L).rescheduleFromDate("18 February 2023"));
        loanRescheduleRequestHelper.rejectLoanRescheduleRequest(rescheduleLoansResponse.getResourceId(), new PostUpdateRescheduleLoansRequest().rejectedOnDate("18 February 2024").locale("en").dateFormat(DATETIME_PATTERN));
        loanRescheduleRequestHelper.createLoanRescheduleRequest(new PostCreateRescheduleLoansRequest().loanId(loanResponse.get().getLoanId()).dateFormat(DATETIME_PATTERN).locale("en").submittedOnDate("18 February 2023").newInterestRate(BigDecimal.ONE).rescheduleReasonId(1L).rescheduleFromDate("18 February 2023"));
    });
}

