    final Integer loanID = applyForLoanApplication(clientID, loanProductID, "0");
    final float FEE_PORTION = 50.0f;
    final float PENALTY_PORTION = 100.0f;
    final float NEXT_FEE_PORTION = 55.0f;
    final float NEXT_PENALTY_PORTION = 105.0f;
    Integer flat = ChargesHelper.createCharges(requestSpec, responseSpec, ChargesHelper.getLoanSpecifiedDueDateJSON(ChargesHelper.CHARGE_CALCULATION_TYPE_FLAT, String.valueOf(FEE_PORTION), false));
    Integer flatSpecifiedDueDate = ChargesHelper.createCharges(requestSpec, responseSpec, ChargesHelper.getLoanSpecifiedDueDateJSON(ChargesHelper.CHARGE_CALCULATION_TYPE_FLAT, String.valueOf(PENALTY_PORTION), true));
    Integer flatNext = ChargesHelper.createCharges(requestSpec, responseSpec, ChargesHelper.getLoanSpecifiedDueDateJSON(ChargesHelper.CHARGE_CALCULATION_TYPE_FLAT, String.valueOf(NEXT_FEE_PORTION), false));
    Integer flatSpecifiedDueDateNext = ChargesHelper.createCharges(requestSpec, responseSpec, ChargesHelper.getLoanSpecifiedDueDateJSON(ChargesHelper.CHARGE_CALCULATION_TYPE_FLAT, String.valueOf(NEXT_PENALTY_PORTION), true));
    HashMap<String, Object> loanStatusHashMap = LoanStatusChecker.getStatusOfLoan(requestSpec, responseSpec, loanID);
    LoanStatusChecker.verifyLoanIsPending(loanStatusHashMap);
    loanStatusHashMap = this.loanTransactionHelper.approveLoan(EXPECTED_DISBURSAL_DATE, loanID);
    LoanStatusChecker.verifyLoanIsApproved(loanStatusHashMap);
    LoanStatusChecker.verifyLoanIsWaitingForDisbursal(loanStatusHashMap);
    LocalDate targetDate = LocalDate.of(2011, 3, 4);
    final String loanDisbursementDate = DATE_FORMATTER.format(targetDate);
    String loanDetails = this.loanTransactionHelper.getLoanDetails(requestSpec, responseSpec, loanID);
    loanStatusHashMap = this.loanTransactionHelper.disburseLoanWithNetDisbursalAmount(loanDisbursementDate, loanID, JsonPath.from(loanDetails).get("netDisbursalAmount").toString());
    LoanStatusChecker.verifyLoanIsActive(loanStatusHashMap);
    ArrayList<HashMap> loanSchedule = this.loanTransactionHelper.getLoanRepaymentSchedule(requestSpec, responseSpec, loanID);
    assertEquals(2, loanSchedule.size());
    assertEquals(0.0f, loanSchedule.get(1).get("feeChargesDue"));
    assertEquals(0.0f, loanSchedule.get(1).get("feeChargesOutstanding"));
    assertEquals(0.0f, loanSchedule.get(1).get("penaltyChargesDue"));
    assertEquals(0.0f, loanSchedule.get(1).get("penaltyChargesOutstanding"));
    assertEquals(10000.0f, loanSchedule.get(1).get("totalDueForPeriod"));
    assertEquals(10000.0f, loanSchedule.get(1).get("totalOutstandingForPeriod"));
