    final String penaltyCharge1AddedDate = DATE_FORMATTER.format(targetDate);
    Integer penalty1LoanChargeId = this.loanTransactionHelper.addChargesForLoan(loanID, LoanTransactionHelper.getSpecifiedDueDateChargesForLoanAsJSON(String.valueOf(flatSpecifiedDueDate), penaltyCharge1AddedDate, String.valueOf(PENALTY_PORTION)));
