        BUSINESS_DATE_HELPER.updateBusinessDate(new BusinessDateRequest().type(BusinessDateType.BUSINESS_DATE.getName()).date("04 October 2023").dateFormat(DATETIME_PATTERN).locale("en"));
        loanTransactionHelper.makeMerchantIssuedRefund(loanResponse.getLoanId(), new PostLoansLoanIdTransactionsRequest().dateFormat(DATETIME_PATTERN).transactionDate("04 October 2023").locale("en").transactionAmount(1000.0));
        loanDetails = loanTransactionHelper.getLoanDetails(loanResponse.getLoanId());
        validateLoanSummaryBalances(loanDetails, 0.0, 1000.0, 0.0, 1000.0, 1000.0);
        validateRepaymentPeriod(loanDetails, 1, 1000.0, 1000.0, 0.0, 0.0, 0.0);
        validateLoanTransaction(loanDetails, 2, 1000.0, 0.0, 1000.0, 0.0);
        assertTrue(loanDetails.getStatus().getOverpaid());
        loanTransactionHelper.reverseLoanTransaction(loanResponse.getLoanId(), repaymentTransaction.getResourceId(), new PostLoansLoanIdTransactionsTransactionIdRequest().dateFormat(DATETIME_PATTERN).transactionDate("04 October 2023").transactionAmount(0.0).locale("en"));
        loanDetails = loanTransactionHelper.getLoanDetails(loanResponse.getLoanId());
        validateLoanSummaryBalances(loanDetails, 0.0, 1000.0, 0.0, 1000.0, null);
        validateRepaymentPeriod(loanDetails, 1, 1000.0, 1000.0, 0.0, 0.0, 1000.0);
        validateLoanTransaction(loanDetails, 2, 1000.0, 1000.0, 0.0, 0.0);
        assertTrue(loanDetails.getStatus().getClosedObligationsMet());
        PostLoansLoanIdChargesResponse penaltyLoanChargeResult = loanTransactionHelper.addChargesForLoan(loanResponse.getLoanId(), new PostLoansLoanIdChargesRequest().chargeId(penaltyCharge.getResourceId()).dateFormat(DATETIME_PATTERN).locale("en").amount(10.0).dueDate("04 October 2023"));
        loanDetails = loanTransactionHelper.getLoanDetails(loanResponse.getLoanId());
        validateLoanSummaryBalances(loanDetails, 10.0, 1000.0, 0.0, 1000.0, null);
        validateRepaymentPeriod(loanDetails, 1, 1000.0, 1000.0, 0.0, 0.0, 1000.0);
        validateRepaymentPeriod(loanDetails, 2, 0.0, 0.0, 0.0, 10.0, 0.0, 10.0, 0.0, 0.0);
        assertTrue(loanDetails.getStatus().getActive());
    } finally {
        globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_BUSINESS_DATE, new PutGlobalConfigurationsRequest().enabled(false));
    }
}

