@ParameterizedTest
@MethodSource("loanProductFactory")
public void loanTransactionChargebackOfFullAmountForOverpaidLoanTest(LoanProductTestBuilder loanProductTestBuilder) {
    // Loan ExternalId
    String loanExternalIdStr = UUID.randomUUID().toString();
    // Delinquency Bucket
    final Integer delinquencyBucketId = DelinquencyBucketsHelper.createDelinquencyBucket(requestSpec, responseSpec);
    final DelinquencyBucketData delinquencyBucket = DelinquencyBucketsHelper.getDelinquencyBucket(requestSpec, responseSpec, delinquencyBucketId);
    // Client and Loan account creation
    final Integer clientId = clientHelper.createClient(ClientHelper.defaultClientCreationRequest()).getClientId().intValue();
    final GetLoanProductsProductIdResponse getLoanProductsProductResponse = createLoanProduct(loanTransactionHelper, delinquencyBucketId, loanProductTestBuilder);
    assertNotNull(getLoanProductsProductResponse);
    final Integer loanId = createLoanAccount(clientId, getLoanProductsProductResponse.getId(), loanExternalIdStr, loanProductTestBuilder.getTransactionProcessingStrategyCode());
    // make Repayments
    final PostLoansLoanIdTransactionsResponse repaymentTransaction_1 = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("5 September 2022").locale("en").transactionAmount(450.0));
    final PostLoansLoanIdTransactionsResponse repaymentTransaction_2 = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("6 September 2022").locale("en").transactionAmount(450.0));
    final PostLoansLoanIdTransactionsResponse repaymentTransaction_3 = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("7 September 2022").locale("en").transactionAmount(300.0));
    GetLoansLoanIdResponse loanDetails = loanTransactionHelper.getLoanDetails((long) loanId);
    // verify loan is overpaid
    assertNotNull(loanDetails);
    assertTrue(loanDetails.getStatus().getOverpaid());
    assertEquals(loanDetails.getTotalOverpaid(), 200.0);
    // verify loan outstanding
    assertNotNull(loanDetails.getSummary());
    assertEquals(loanDetails.getSummary().getTotalOutstanding(), 0.0);
    // verify last transaction amount distribution
    GetLoansLoanIdTransactionsTransactionIdResponse loanTransaction = loanTransactionHelper.getLoanTransaction(loanId, repaymentTransaction_3.getResourceId().intValue());
    assertNotNull(loanTransaction);
    assertEquals(loanTransaction.getAmount(), 300.0);
    assertEquals(loanTransaction.getPrincipalPortion(), 100.0);
    // chargeback for full amount on last repayment for which the amount is 300 and principal is 100 due to
    // overpayment adjustment
    // This verifies that validation for chargeback amount is with total amount of transaction and not principal
    // portion.
    PostLoansLoanIdTransactionsResponse chargebackTransactionResponse = loanTransactionHelper.chargebackLoanTransaction(loanExternalIdStr, repaymentTransaction_3.getResourceId(), new PostLoansLoanIdTransactionsTransactionIdRequest().locale("en").transactionAmount(300.0).paymentTypeId(1L));
    assertNotNull(chargebackTransactionResponse);
    GetLoansLoanIdResponse loanDetailsAfterChargeback = loanTransactionHelper.getLoanDetails((long) loanId);
    assertNotNull(loanDetailsAfterChargeback);
    assertTrue(loanDetailsAfterChargeback.getStatus().getActive());
    // verify loan outstanding
    assertNotNull(loanDetailsAfterChargeback.getSummary());
    assertEquals(loanDetailsAfterChargeback.getSummary().getTotalOutstanding(), 100.0);
    // verify chargeback transaction amount distribution
    GetLoansLoanIdTransactionsTransactionIdResponse chargebackTransaction = loanTransactionHelper.getLoanTransaction(loanId, chargebackTransactionResponse.getResourceId().intValue());
    assertNotNull(chargebackTransaction);
    assertEquals(chargebackTransaction.getAmount(), 300.0);
    assertEquals(chargebackTransaction.getPrincipalPortion(), 100.0);
}

