public void loanTransactionReprocessForAddChargeTest() {
    try {
        // Set business date
        LocalDate businessDate = LocalDate.of(2023, 3, 15);
        globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_BUSINESS_DATE, new PutGlobalConfigurationsRequest().enabled(true));
        BusinessDateHelper.updateBusinessDate(REQUEST_SPEC, RESPONSE_SPEC, BusinessDateType.BUSINESS_DATE, businessDate);
        // Accounts oof periodic accrual
        final Account assetAccount = ACCOUNT_HELPER.createAssetAccount();
        final Account incomeAccount = ACCOUNT_HELPER.createIncomeAccount();
        final Account expenseAccount = ACCOUNT_HELPER.createExpenseAccount();
        final Account overpaymentAccount = ACCOUNT_HELPER.createLiabilityAccount();
        // Loan ExternalId
        String loanExternalIdStr = UUID.randomUUID().toString();
        final Integer clientId = CLIENT_HELPER.createClient(ClientHelper.defaultClientCreationRequest()).getClientId().intValue();
        final Integer loanProductId = createLoanProduct(assetAccount, incomeAccount, expenseAccount, overpaymentAccount);
        final Integer loanId = createLoanAccount(clientId, loanProductId, loanExternalIdStr);
        // disburse principal amount
        LOAN_TRANSACTION_HELPER.disburseLoanWithTransactionAmount("15 February 2023", loanId, "1000");
        // add loan charge
        // apply fee
        Integer feeCharge = ChargesHelper.createCharges(REQUEST_SPEC, RESPONSE_SPEC, ChargesHelper.getLoanSpecifiedDueDateJSON(ChargesHelper.CHARGE_CALCULATION_TYPE_FLAT, "50", false));
        LocalDate targetDate = LocalDate.of(2023, 2, 22);
        final String feeCharge1AddedDate = DATE_FORMATTER.format(targetDate);
        Integer feeLoanChargeId = LOAN_TRANSACTION_HELPER.addChargesForLoan(loanId, LoanTransactionHelper.getSpecifiedDueDateChargesForLoanAsJSON(String.valueOf(feeCharge), feeCharge1AddedDate, "50"));
        // Set Loan transaction externalId for transaction getting reversed and replayed
        String loanTransactionExternalIdStr = UUID.randomUUID().toString();
        // make repayment
        final PostLoansLoanIdTransactionsResponse repaymentTransaction = LOAN_TRANSACTION_HELPER.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat("dd MMMM yyyy").transactionDate("20 February 2023").locale("en").transactionAmount(50.0).externalId(loanTransactionExternalIdStr));
        // verify transaction amounts
        verifyTransaction(LocalDate.of(2023, 2, 20), 50.0f, 0.0f, 0.0f, 50.0f, 0.0f, loanId, "repayment");
        // add loan charge for a date later than repayment date
        // apply penalty
        targetDate = LocalDate.of(2023, 2, 22);
        Integer penalty = ChargesHelper.createCharges(REQUEST_SPEC, RESPONSE_SPEC, ChargesHelper.getLoanSpecifiedDueDateJSON(ChargesHelper.CHARGE_CALCULATION_TYPE_FLAT, "10", true));
        final String penaltyCharge1AddedDate = DATE_FORMATTER.format(targetDate);
        Integer penalty1LoanChargeId = LOAN_TRANSACTION_HELPER.addChargesForLoan(loanId, LoanTransactionHelper.getSpecifiedDueDateChargesForLoanAsJSON(String.valueOf(penalty), penaltyCharge1AddedDate, "10"));
        // verify no reverse replay
        GetLoansLoanIdTransactionsTransactionIdResponse getLoansTransactionResponse = LOAN_TRANSACTION_HELPER.getLoanTransactionDetails((long) loanId, loanTransactionExternalIdStr);
        assertNotNull(getLoansTransactionResponse);
        assertEquals(0, getLoansTransactionResponse.getTransactionRelations().size());
        // add loan charge for a date earlier than repayment date
        targetDate = LocalDate.of(2023, 2, 18);
        Integer penalty_1 = ChargesHelper.createCharges(REQUEST_SPEC, RESPONSE_SPEC, ChargesHelper.getLoanSpecifiedDueDateJSON(ChargesHelper.CHARGE_CALCULATION_TYPE_FLAT, "10", true));
        final String penaltyCharge1AddedDate_1 = DATE_FORMATTER.format(targetDate);
        Integer penalty1LoanChargeId_1 = LOAN_TRANSACTION_HELPER.addChargesForLoan(loanId, LoanTransactionHelper.getSpecifiedDueDateChargesForLoanAsJSON(String.valueOf(penalty_1), penaltyCharge1AddedDate_1, "10"));
        // verify reverse replay
        getLoansTransactionResponse = LOAN_TRANSACTION_HELPER.getLoanTransactionDetails((long) loanId, loanTransactionExternalIdStr);
        assertNotNull(getLoansTransactionResponse);
        assertEquals(1, getLoansTransactionResponse.getTransactionRelations().size());
        // verify transaction amounts
        verifyTransaction(LocalDate.of(2023, 2, 20), 50.0f, 40.0f, 0.0f, 0.0f, 10.0f, loanId, "repayment");
    } finally {
        globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_BUSINESS_DATE, new PutGlobalConfigurationsRequest().enabled(false));
    }
}

@Test
public void loanTransactionReverseReplayWithChargeOff() {
    runAt("4 October 2022", () -> {
        final Account assetAccount = accountHelper.createAssetAccount();
        final Account chargeOffFraudExpenseAccount = accountHelper.createExpenseAccount();
        final Account chargeOffExpenseAccount = accountHelper.createExpenseAccount();
        // Loan ExternalId
        String loanExternalIdStr = UUID.randomUUID().toString();
        // Client and Loan account creation
        final Long clientId = clientHelper.createClient(ClientHelper.defaultClientCreationRequest()).getClientId();
        PostLoanProductsRequest loanProductsRequest = createOnePeriod30DaysLongNoInterestPeriodicAccrualProduct().chargeOffExpenseAccountId(chargeOffExpenseAccount.getAccountID().longValue()).chargeOffFraudExpenseAccountId(chargeOffFraudExpenseAccount.getAccountID().longValue()).loanPortfolioAccountId(assetAccount.getAccountID().longValue());
        PostLoanProductsResponse loanProductResponse = loanProductHelper.createLoanProduct(loanProductsRequest);
        Long loanId = applyAndApproveLoan(clientId, loanProductResponse.getResourceId(), "2 September 2022", 1000.0, 1, postLoansRequest -> {
            postLoansRequest.externalId(loanExternalIdStr);
        });
        disburseLoan(loanId, BigDecimal.valueOf(1000.00), "2 September 2022");
        // make repayment
        String loanTransactionExternalIdStr = UUID.randomUUID().toString();
        PostLoansLoanIdTransactionsResponse repaymentTransaction = loanTransactionHelper.makeLoanRepayment(loanExternalIdStr, new PostLoansLoanIdTransactionsRequest().dateFormat(DATETIME_PATTERN).transactionDate("03 October 2022").locale("en").transactionAmount(10.0).externalId(loanTransactionExternalIdStr));
        // mark loan as fraud
        final String command = "markAsFraud";
        String payload = loanTransactionHelper.getLoanFraudPayloadAsJSON("fraud", "true");
        loanTransactionHelper.modifyLoanCommand(loanId.intValue(), command, payload, responseSpec);
        // charge-off loan
        String randomText = Utils.randomStringGenerator("en", 5) + Utils.randomNumberGenerator(6) + Utils.randomStringGenerator("is", 5);
        Integer chargeOffReasonId = CodeHelper.createChargeOffCodeValue(requestSpec, responseSpec, randomText, 1);
        String transactionExternalId = UUID.randomUUID().toString();
        PostLoansLoanIdTransactionsResponse chargeOffTransaction = loanTransactionHelper.chargeOffLoan((long) loanId, new PostLoansLoanIdTransactionsRequest().transactionDate("4 October 2022").locale("en").dateFormat("dd MMMM yyyy").externalId(transactionExternalId).chargeOffReasonId((long) chargeOffReasonId));
        updateBusinessDate("6 October 2022");
        loanTransactionHelper.reverseLoanTransaction(loanExternalIdStr, repaymentTransaction.getResourceId(), new PostLoansLoanIdTransactionsTransactionIdRequest().transactionDate("6 October 2022").locale("en").dateFormat(DATETIME_PATTERN).transactionAmount(0.0));
        ArrayList<HashMap> journalEntriesForChargeOffTransaction = journalEntryHelper.getJournalEntriesByTransactionId("L" + chargeOffTransaction.getResourceId());
        assertNotNull(journalEntriesForChargeOffTransaction);
        List<HashMap> assetAccountJournalEntries = //
        journalEntriesForChargeOffTransaction.stream().filter(//
        journalEntry -> assetAccount.getAccountID().equals(journalEntry.get("glAccountId"))).toList();
        List<HashMap> expenseAccountJournalEntries = //
        journalEntriesForChargeOffTransaction.stream().filter(//
        journalEntry -> chargeOffFraudExpenseAccount.getAccountID().equals(journalEntry.get("glAccountId"))).toList();
        assertEquals(2, assetAccountJournalEntries.size());
        assertEquals(2, expenseAccountJournalEntries.size());
    });
}

