@Test
public void testMakerCheckerOn() {
    globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.MAKER_CHECKER, new PutGlobalConfigurationsRequest().enabled(true));
    globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_SAME_MAKER_CHECKER, new PutGlobalConfigurationsRequest().enabled(false));
    try {
        // client permission - maker-checker disabled
        PutPermissionsRequest putPermissionsRequest = new PutPermissionsRequest().putPermissionsItem("CREATE_CLIENT", false);
        rolesHelper.updatePermissions(putPermissionsRequest);
        putPermissionsRequest = new PutPermissionsRequest().putPermissionsItem("ACTIVATE_CLIENT", false);
        rolesHelper.updatePermissions(putPermissionsRequest);
        Integer roleId = RolesHelper.createRole(requestSpec, responseSpec);
        Map<String, Boolean> permissionMap = Map.of("CREATE_CLIENT", true, "CREATE_CLIENT_CHECKER", true, "ACTIVATE_CLIENT", true, "ACTIVATE_CLIENT_CHECKER", true, "WITHDRAWAL_SAVINGSACCOUNT", true, "WITHDRAWAL_SAVINGSACCOUNT_CHECKER", true);
        RolesHelper.addPermissionsToRole(requestSpec, responseSpec, roleId, permissionMap);
        final Integer staffId = StaffHelper.createStaff(this.requestSpec, this.responseSpec);
        // create maker user
        String maker = Utils.uniqueRandomStringGenerator("user", 8);
        final Integer makerUserId = (Integer) UserHelper.createUser(this.requestSpec, this.responseSpec, roleId, staffId, maker, "A1b2c3d4e5f$", "resourceId");
        // create client - maker-checker disabled
        RequestSpecification makerRequestSpec = new RequestSpecBuilder().setContentType(ContentType.JSON).build().header("Authorization", "Basic " + Utils.loginIntoServerAndGetBase64EncodedAuthenticationKey(maker, "A1b2c3d4e5f$"));
        Integer clientId = ClientHelper.createClient(makerRequestSpec, this.responseSpec);
        assertNotNull(clientId);
        ClientHelper.verifyClientCreatedOnServer(requestSpec, this.responseSpec, clientId);
        final Integer savingsId = createApproveActivateSavingsAccountDailyPosting(clientId, START_DATE_STRING);
        assertNotNull(savingsId);
        Integer transactionId = (Integer) savingsAccountHelper.depositToSavingsAccount(savingsId, "1000", TRANSACTION_DATE_STRING, CommonConstants.RESPONSE_RESOURCE_ID);
        assertNotNull(transactionId);
        // client and saving permission - maker-checker enabled
        putPermissionsRequest = new PutPermissionsRequest().putPermissionsItem("ACTIVATE_CLIENT", true);
        rolesHelper.updatePermissions(putPermissionsRequest);
        putPermissionsRequest = new PutPermissionsRequest().putPermissionsItem("WITHDRAWAL_SAVINGSACCOUNT", true);
        rolesHelper.updatePermissions(putPermissionsRequest);
        // create client - maker-checker enabled
        clientId = ClientHelper.createClient(makerRequestSpec, this.responseSpec);
        assertNull(clientId, "Client is created on the server");
        List<Map<String, Object>> auditDetails = makercheckersHelper.getMakerCheckerList(Map.of("actionName", "CREATE", "entityName", "CLIENT", "makerId", makerUserId.toString()));
        assertEquals(1, auditDetails.size(), "More than one command exists");
        Long clientCommandId = ((Double) auditDetails.get(0).get("id")).longValue();
        // savings withdrawal - maker-checker enabled
        SavingsAccountHelper makerSavingsHelper = new SavingsAccountHelper(makerRequestSpec, this.responseSpec);
        Integer withdrawalId = (Integer) makerSavingsHelper.withdrawalFromSavingsAccount(savingsId, "100", TRANSACTION_DATE_STRING, CommonConstants.RESPONSE_RESOURCE_ID);
        assertNull(withdrawalId, "Withdrawal performed on the server");
        auditDetails = makercheckersHelper.getMakerCheckerList(Map.of("actionName", "WITHDRAWAL", "entityName", "SAVINGSACCOUNT", "makerId", makerUserId.toString()));
        assertEquals(1, auditDetails.size(), "More than one command exists");
        Long savingCommandId = ((Double) auditDetails.get(0).get("id")).longValue();
        // check by the same user should fail
        ResponseSpecification failedResponseSpec = new ResponseSpecBuilder().expectStatusCode(400).build();
        MakercheckersHelper.approveMakerCheckerEntry(makerRequestSpec, failedResponseSpec, clientCommandId);
        MakercheckersHelper.approveMakerCheckerEntry(makerRequestSpec, failedResponseSpec, savingCommandId);
        // create checker user
        String checker = Utils.uniqueRandomStringGenerator("user", 8);
        final Integer checkerUserId = (Integer) UserHelper.createUser(this.requestSpec, this.responseSpec, roleId, staffId, checker, "A1b2c3d4e5f$", "resourceId");
        RequestSpecification checkerRequestSpec = new RequestSpecBuilder().setContentType(ContentType.JSON).build().header("Authorization", "Basic " + Utils.loginIntoServerAndGetBase64EncodedAuthenticationKey(checker, "A1b2c3d4e5f$"));
        // check by another checker user should succeed
        HashMap<?, ?> response = MakercheckersHelper.approveMakerCheckerEntry(checkerRequestSpec, responseSpec, clientCommandId);
        assertNotNull(response);
        clientId = (Integer) response.get("clientId");
        assertNotNull(clientId);
        ClientHelper.verifyClientCreatedOnServer(requestSpec, responseSpec, clientId);
        response = MakercheckersHelper.approveMakerCheckerEntry(checkerRequestSpec, responseSpec, savingCommandId);
        assertNotNull(response);
        withdrawalId = (Integer) response.get("resourceId");
        assertNotNull(withdrawalId);
        // add checker superuser permission - actions are performed in one step
        permissionMap = Map.of("CHECKER_SUPER_USER", true);
        RolesHelper.addPermissionsToRole(requestSpec, responseSpec, roleId, permissionMap);
        clientId = ClientHelper.createClient(makerRequestSpec, this.responseSpec);
        assertNotNull(clientId);
        ClientHelper.verifyClientCreatedOnServer(requestSpec, this.responseSpec, clientId);
        withdrawalId = (Integer) makerSavingsHelper.withdrawalFromSavingsAccount(savingsId, "100", TRANSACTION_DATE_STRING, CommonConstants.RESPONSE_RESOURCE_ID);
        assertNotNull(withdrawalId);
    } finally {
        globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.MAKER_CHECKER, new PutGlobalConfigurationsRequest().enabled(false));
        globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_SAME_MAKER_CHECKER, new PutGlobalConfigurationsRequest().enabled(true));
        PutPermissionsRequest putPermissionsRequest = new PutPermissionsRequest().putPermissionsItem("WITHDRAWAL_SAVINGSACCOUNT", false);
        rolesHelper.updatePermissions(putPermissionsRequest);
    }
}

