        verifyRepaymentSchedule(loanId, installment(100.0, null, "01 January 2024"), installment(14.97, 5.03, 0.0, true, "01 February 2024"), installment(15.7, 4.3, 20.0, false, "01 March 2024"), installment(16.7, 3.3, 20.0, false, "01 April 2024"), installment(17.61, 2.39, 20.0, false, "01 May 2024"), installment(18.58, 1.42, 20.0, false, "01 June 2024"), installment(16.44, 0.41, 7.85, false, "01 July 2024"));
    });
    runAt("1 March 2024", () -> {
        Long loanId = loanIdRef.get();
