@Test
public void testSavingsInterestPosting_Works_ForMultipleAccounts() {
    List<AccountWithDepositAmount> accounts = new ArrayList<>();
    runAt("01 January 2023", () -> {
        // Create Client
        Long clientId = clientHelper.createClient(ClientHelper.defaultClientCreationRequest()).getClientId();
        // Create product
        PostSavingsProductsRequest productsRequest = dailyInterestPostingProduct();
        PostSavingsProductsResponse product = createProduct(productsRequest);
        Long productId = product.getResourceId();
        // Create accounts
        //
        IntStream.range(0, 200).parallel().mapToObj(//
        i -> applySavingsRequest(clientId, productId, "01 January 2023")).map(//
        this::applySavingsAccount).mapToLong(//
        PostSavingsAccountsResponse::getResourceId).forEach(savingsId -> {
            approveSavingsAccount(savingsId, "01 January 2023");
            activateSavingsAccount(savingsId, "01 January 2023");
            accounts.add(new AccountWithDepositAmount(savingsId));
        });
    });
    runFromToInclusive("02 January 2023", "10 January 2023", (date) -> {
        SecureRandom rnd = new SecureRandom();
        accounts.parallelStream().forEach(account -> {
            long lAmount = rnd.nextLong(10_000_000L);
            BigDecimal amount = BigDecimal.valueOf(lAmount);
            deposit(account.savingsId, date, amount);
            account.addDeposit(amount);
        });
    });
    runAt("11 January 2023", () -> {
        String jobName = "Post Interest For Savings";
        schedulerJobHelper.executeAndAwaitJob(jobName);
        accounts.parallelStream().forEach(account -> {
            SavingsAccountData accountData = getSavingsAccount(account.savingsId);
            BigDecimal accountBalance = accountData.getSummary().getAccountBalance();
            BigDecimal accountBalanceByTransactions = accountData.getTransactions().stream().map(SavingsAccountTransactionData::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
            assertThat(accountBalance).withFailMessage("Account balance (%s) and calculated balance (%s) from transactions do not match", accountBalance, accountBalanceByTransactions).isEqualByComparingTo(accountBalanceByTransactions);
            BigDecimal summedDepositAmount = accountData.getTransactions().stream().filter(tx -> tx.getTransactionType().getDeposit()).map(SavingsAccountTransactionData::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
            assertThat(summedDepositAmount).withFailMessage("Calculated balance (%s) from deposit transactions and submitted deposit balance (%s) do not match", accountBalance, summedDepositAmount).isEqualByComparingTo(account.depositedAmount);
        });
    });
}

