    HashMap savingsStatusHashMap = this.savingsAccountHelper.activateSavings(savingsId);
    SavingsStatusChecker.verifySavingsIsActive(savingsStatusHashMap);
    float balance = 0F;
    float transactionAmount = 100F;
    Integer depositTransactionId = (Integer) this.savingsAccountHelper.depositToSavingsAccount(savingsId, String.valueOf(transactionAmount), SavingsAccountHelper.TRANSACTION_DATE, CommonConstants.RESPONSE_RESOURCE_ID);
    Assertions.assertNotNull(depositTransactionId);
    balance = balance + transactionAmount;
    HashMap summary = this.savingsAccountHelper.getSavingsSummary(savingsId);
    assertEquals(balance, summary.get("availableBalance"), "Verifying Balance after deposit");
    Integer withdrawalTransactionId = (Integer) this.savingsAccountHelper.withdrawalFromSavingsAccount(savingsId, String.valueOf(transactionAmount), SavingsAccountHelper.TRANSACTION_DATE, CommonConstants.RESPONSE_RESOURCE_ID);
    Assertions.assertNotNull(withdrawalTransactionId);
    balance = balance - transactionAmount;
    summary = this.savingsAccountHelper.getSavingsSummary(savingsId);
    assertEquals(balance, summary.get("availableBalance"), "Verifying Balance after withdrawal");
    float holdAmount = 50F;
    Integer holdTransactionId = (Integer) this.savingsAccountHelper.holdAmountInSavingsAccount(savingsId, String.valueOf(holdAmount), false, SavingsAccountHelper.TRANSACTION_DATE, CommonConstants.RESPONSE_RESOURCE_ID);
    Assertions.assertNotNull(holdTransactionId);
    balance = balance - holdAmount;
    summary = this.savingsAccountHelper.getSavingsSummary(savingsId);
    assertEquals(balance, summary.get("availableBalance"), "Verifying Balance after hold amount");
    this.savingsAccountHelper.releaseAmount(savingsId, holdTransactionId);
    balance = balance + holdAmount;
    summary = this.savingsAccountHelper.getSavingsSummary(savingsId);
    assertEquals(balance, summary.get("availableBalance"), "Verifying Balance after release amount");
    depositTransactionId = (Integer) this.savingsAccountHelper.depositToSavingsAccount(savingsId, String.valueOf(transactionAmount), SavingsAccountHelper.TRANSACTION_DATE, CommonConstants.RESPONSE_RESOURCE_ID);
    Assertions.assertNotNull(depositTransactionId);
    balance = balance + transactionAmount;
    summary = this.savingsAccountHelper.getSavingsSummary(savingsId);
    assertEquals(balance, summary.get("availableBalance"), "Verifying Balance after hold-release-deposit");
}

