    this.savingsAccountHelper.approveSavings(savingsId);
    HashMap savingsStatusHashMap = this.savingsAccountHelper.activateSavings(savingsId);
    SavingsStatusChecker.verifySavingsIsActive(savingsStatusHashMap);
    SavingsAccountHelper concurrentHelper = new SavingsAccountHelper(requestSpec, concurrentResponseSpec);
    String transactionDate = SavingsAccountHelper.TRANSACTION_DATE;
    String transactionAmount = "10";
    ExecutorService executor = Executors.newFixedThreadPool(30);
    for (int i = 0; i < 10; i++) {
        log.info("Starting concurrent transaction number {}", i);
        SavingsTransactionData transactionData = SavingsTransactionData.builder().transactionDate(transactionDate).transactionAmount(transactionAmount).paymentTypeId(PAYMENT_TYPE_ID).note("note_" + i).build();
        Runnable worker = new TransactionExecutor(concurrentHelper, savingsId, transactionData);
        executor.execute(worker);
    }
    executor.shutdown();
    // Wait until all threads are finish
    while (!executor.isTerminated()) {
    }
    log.info("\nFinished all threads");
}

@Test
public void testConcurrentSavingsBatchTransactions() {
    final Integer clientID = ClientHelper.createClient(this.requestSpec, this.responseSpec);
    ClientHelper.verifyClientCreatedOnServer(this.requestSpec, this.responseSpec, clientID);
    final Integer savingsProductId = createSavingsProductDailyPosting();
    assertNotNull(savingsProductId);
    final Integer savingsId = this.savingsAccountHelper.applyForSavingsApplication(clientID, savingsProductId, ACCOUNT_TYPE_INDIVIDUAL);
    this.savingsAccountHelper.approveSavings(savingsId);
    HashMap savingsStatusHashMap = this.savingsAccountHelper.activateSavings(savingsId);
    SavingsStatusChecker.verifySavingsIsActive(savingsStatusHashMap);
    // creating datatable for client entity
    final HashMap<String, Object> columnMap = new HashMap<>();
    String datatableName = Utils.uniqueRandomStringGenerator("dt_savings_transaction_", 5).toLowerCase();
    columnMap.put("datatableName", datatableName);
    columnMap.put("apptableName", "m_savings_account_transaction");
    columnMap.put("multiRow", false);
    String string1 = "string1";
    String string2 = "string2";
    List<String> columnNames = List.of(string1, string2);
    final List<HashMap<String, Object>> datatableColumnsList = new ArrayList<>();
    addDatatableColumn(datatableColumnsList, string1, "String", false, 10, null);
    addDatatableColumn(datatableColumnsList, string2, "String", true, 12, null);
    columnMap.put("columns", datatableColumnsList);
    String datatableJson = new Gson().toJson(columnMap);
    this.datatableHelper.createDatatable(datatableJson, "");
    SavingsAccountHelper batchWithTransactionHelper = new SavingsAccountHelper(requestSpec, concurrentResponseSpec);
    SavingsAccountHelper batchWithoutTransactionHelper = new SavingsAccountHelper(requestSpec, new ResponseSpecBuilder().expectStatusCode(anyOf(is(SC_OK), is(SC_CONFLICT), is(SC_FORBIDDEN))).build());
    String transactionDate = SavingsAccountHelper.TRANSACTION_DATE;
    String transactionAmount = "10";
    ExecutorService executor = Executors.newFixedThreadPool(30);
    ArrayList<Future<?>> results = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        log.info("Starting concurrent transaction number {}", i);
        SavingsTransactionData transactionData = SavingsTransactionData.builder().transactionDate(transactionDate).transactionAmount(transactionAmount).paymentTypeId(PAYMENT_TYPE_ID).note("note_" + i).build();
        Runnable workerWithTransaction = new TransactionExecutor(batchWithTransactionHelper, savingsId, transactionData, true, datatableName, columnNames);
        results.add(executor.submit(workerWithTransaction));
        Runnable workerWithoutTransaction = new TransactionExecutor(batchWithoutTransactionHelper, savingsId, transactionData, false, datatableName, columnNames);
        results.add(executor.submit(workerWithoutTransaction));
    }
    executor.shutdown();
    // Wait until all threads are finish
    while (!executor.isTerminated()) {
    }
    this.datatableHelper.deleteDatatable(datatableName);
    try {
        for (Future<?> result : results) {
            assertNull(result.get());
        }
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
    log.info("\nFinished all threads");
}

@Test
public void testDeadlockSavingsBatchTransactions() {
    final Integer clientID = ClientHelper.createClient(requestSpec, responseSpec);
    ClientHelper.verifyClientCreatedOnServer(requestSpec, responseSpec, clientID);
    final Integer savingsProductId = createSavingsProductDailyPosting();
    assertNotNull(savingsProductId);
    final Integer savingsId1 = savingsAccountHelper.applyForSavingsApplication(clientID, savingsProductId, ACCOUNT_TYPE_INDIVIDUAL);
    savingsAccountHelper.approveSavings(savingsId1);
    savingsAccountHelper.activateSavings(savingsId1);
    final Integer savingsId2 = savingsAccountHelper.applyForSavingsApplication(clientID, savingsProductId, ACCOUNT_TYPE_INDIVIDUAL);
    savingsAccountHelper.approveSavings(savingsId2);
    savingsAccountHelper.activateSavings(savingsId2);
    SavingsAccountHelper batchWithTransactionHelper = new SavingsAccountHelper(requestSpec, deadlockResponseSpec);
    String transactionDate = SavingsAccountHelper.TRANSACTION_DATE;
    String transactionAmount = "10";
    ExecutorService executor = Executors.newFixedThreadPool(30);
    ArrayList<Future<?>> results = new ArrayList<>();
    for (int i = 0; i < 5; i++) {
        log.info("Starting concurrent transaction number {}", i);
        SavingsTransactionData transactionData1 = SavingsTransactionData.builder().transactionDate(transactionDate).transactionAmount(transactionAmount).paymentTypeId(PAYMENT_TYPE_ID).note("note1_" + i).build();
        results.add(executor.submit(() -> {
            runDeadlockBatch(batchWithTransactionHelper, savingsId1, savingsId2, transactionData1);
        }));
        SavingsTransactionData transactionData2 = SavingsTransactionData.builder().transactionDate(transactionDate).transactionAmount(transactionAmount).paymentTypeId(PAYMENT_TYPE_ID).note("note2_" + i).build();
        results.add(executor.submit(() -> {
            runDeadlockBatch(batchWithTransactionHelper, savingsId2, savingsId1, transactionData2);
        }));
    }
    executor.shutdown();
    // Wait until all threads are finish
    while (!executor.isTerminated()) {
    }
    try {
        for (Future<?> result : results) {
            assertNull(result.get());
        }
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
    log.info("\nFinished all threads");
}

@Test
public void testSavingsDailyInterestPosting() {
    LocalDate today = Utils.getLocalDateOfTenant();
    try {
        globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_BUSINESS_DATE, new PutGlobalConfigurationsRequest().enabled(true));
        BusinessDateHelper.updateBusinessDate(requestSpec, responseSpec, BusinessDateType.BUSINESS_DATE, today);
        // client activation, savings activation and 1st transaction date
        final String startDate = "01 November 2021";
        final Integer clientID = ClientHelper.createClient(this.requestSpec, this.responseSpec, startDate);
        Assertions.assertNotNull(clientID);
        final Integer savingsId = createSavingsAccountDailyPosting(clientID, startDate);
        this.savingsAccountHelper.depositToSavingsAccount(savingsId, "1000", startDate, CommonConstants.RESPONSE_RESOURCE_ID);
        /**
         * Perform Post interest transaction and verify the posted transaction date
         */
        this.savingsAccountHelper.postInterestForSavings(savingsId);
        HashMap accountDetails = this.savingsAccountHelper.getSavingsDetails(savingsId);
        ArrayList<HashMap<String, Object>> transactions = (ArrayList<HashMap<String, Object>>) accountDetails.get("transactions");
        HashMap<String, Object> interestPostingTransaction = transactions.get(transactions.size() - 2);
        for (Map.Entry<String, Object> entry : interestPostingTransaction.entrySet()) {
            LOG.info("{} - {}", entry.getKey(), entry.getValue().toString());
        }
        assertEquals("0.274", interestPostingTransaction.get("amount").toString(), "Equality check for interest posted amount");
        assertEquals("[2021, 11, 2]", interestPostingTransaction.get("date").toString(), "Date check for Interest Posting transaction");
        List<Integer> submittedOnDateStringList = (List<Integer>) interestPostingTransaction.get("submittedOnDate");
        LocalDate submittedOnDate = submittedOnDateStringList.stream().collect(Collectors.collectingAndThen(Collectors.toList(), list -> LocalDate.of(list.get(0), list.get(1), list.get(2))));
        assertTrue(DateUtils.isEqual(submittedOnDate, today), "Submitted On Date check for Interest Posting transaction");
    } finally {
        globalConfigurationHelper.updateGlobalConfiguration(GlobalConfigurationConstants.ENABLE_BUSINESS_DATE, new PutGlobalConfigurationsRequest().enabled(false));
    }
}

