@Test
public void testTwofactorLogin() throws IOException, MessagingException {
    assertEquals(0, greenMail.getReceivedMessages().length);
    performServerPost(requestSpec, responseSpec, "/fineract-provider/api/v1/twofactor?deliveryMethod=email&extendedToken=false&" + TENANT_IDENTIFIER, "", "");
    assertEquals(1, greenMail.getReceivedMessages().length);
    Pattern p = Pattern.compile("token is (.+).");
    Matcher m = p.matcher((CharSequence) greenMail.getReceivedMessages()[0].getContent());
    String token = null;
    while (m.find()) {
        token = m.group(1);
    }
    assertNotNull(token);
    String tfaToken = performServerPost(requestSpec, responseSpec, "/fineract-provider/api/v1/twofactor/validate?token=" + token + "&" + TENANT_IDENTIFIER, "", "token");
    assertNotNull(tfaToken);
    RequestSpecification requestSpecWithTFA = //
    new RequestSpecBuilder().setContentType(//
    ContentType.JSON).addHeader("Fineract-Platform-TFA-Token", //
    tfaToken).addHeader("Authorization", //
    "Basic " + basicAuthenticationKey).build();
    performServerGet(requestSpecWithTFA, responseSpec, "/fineract-provider/api/v1/offices/1?" + TENANT_IDENTIFIER, "");
    performServerPost(requestSpecWithTFA, responseSpec, "/fineract-provider/api/v1/twofactor/invalidate?" + TENANT_IDENTIFIER, "{ \"token\": \"" + tfaToken + "\" }", "");
    performServerGet(requestSpecWithTFA, responseSpec401, "/fineract-provider/api/v1/offices/1?" + TENANT_IDENTIFIER, "");
}

@Test
public void testTfaConfigSettings() throws IOException, MessagingException {
    assertEquals(0, greenMail.getReceivedMessages().length);
    performServerPost(requestSpec, responseSpec, "/fineract-provider/api/v1/twofactor?deliveryMethod=email&extendedToken=false&" + TENANT_IDENTIFIER, "", "");
    assertEquals(1, greenMail.getReceivedMessages().length);
    Pattern p = Pattern.compile("token is (.+).");
    Matcher m = p.matcher((CharSequence) greenMail.getReceivedMessages()[0].getContent());
    String token = null;
    while (m.find()) {
        token = m.group(1);
    }
    assertNotNull(token);
    String tfaToken = performServerPost(requestSpec, responseSpec, "/fineract-provider/api/v1/twofactor/validate?token=" + token + "&" + TENANT_IDENTIFIER, "", "token");
    assertNotNull(tfaToken);
    RequestSpecification requestSpecWithTFA = //
    new RequestSpecBuilder().setContentType(//
    ContentType.JSON).addHeader("Fineract-Platform-TFA-Token", //
    tfaToken).addHeader("Authorization", //
    "Basic " + basicAuthenticationKey).build();
    // Get the configuration and check one of the values (OTP token length)
    LinkedHashMap<String, Object> json = performServerGet(requestSpecWithTFA, responseSpec, "/fineract-provider/api/v1/twofactor/configure?" + TENANT_IDENTIFIER, "");
    assertEquals(json.get("otp-token-length"), token.length());
    // Update OTP token length
    performServerPut(requestSpecWithTFA, responseSpec, "/fineract-provider/api/v1/twofactor/configure?" + TENANT_IDENTIFIER, "{\"otp-token-length\": 10 }", "");
    // Invalidate token for re-login
    performServerPost(requestSpecWithTFA, responseSpec, "/fineract-provider/api/v1/twofactor/invalidate?" + TENANT_IDENTIFIER, "{ \"token\": \"" + tfaToken + "\" }", "");
    // Login again
    performServerPost(requestSpec, responseSpec, "/fineract-provider/api/v1/twofactor?deliveryMethod=email&extendedToken=false&" + TENANT_IDENTIFIER, "", "");
    assertEquals(2, greenMail.getReceivedMessages().length);
    Matcher m2 = p.matcher((CharSequence) greenMail.getReceivedMessages()[1].getContent());
    String token2 = null;
    while (m2.find()) {
        token2 = m2.group(1);
    }
    assertNotNull(token2);
    // Check that the configuration has worked and length is now 10
    assertEquals(10, token2.length());
    tfaToken = performServerPost(requestSpec, responseSpec, "/fineract-provider/api/v1/twofactor/validate?token=" + token2 + "&" + TENANT_IDENTIFIER, "", "token");
    assertNotNull(tfaToken);
    requestSpecWithTFA = //
    new RequestSpecBuilder().setContentType(//
    ContentType.JSON).addHeader("Fineract-Platform-TFA-Token", //
    tfaToken).addHeader("Authorization", //
    "Basic " + basicAuthenticationKey).build();
    // Get the configuration and check one of the values (OTP token length)
    json = performServerGet(requestSpecWithTFA, responseSpec, "/fineract-provider/api/v1/twofactor/configure?" + TENANT_IDENTIFIER, "");
    assertEquals(json.get("otp-token-length"), token2.length());
    // Update OTP token length back to original value
    performServerPut(requestSpecWithTFA, responseSpec, "/fineract-provider/api/v1/twofactor/configure?" + TENANT_IDENTIFIER, "{\"otp-token-length\": " + token.length() + "}", "");
    // Check that configuration has been reset
    json = performServerGet(requestSpecWithTFA, responseSpec, "/fineract-provider/api/v1/twofactor/configure?" + TENANT_IDENTIFIER, "");
    assertEquals(json.get("otp-token-length"), token.length());
    // Invalidate token for re-login
    performServerPost(requestSpecWithTFA, responseSpec, "/fineract-provider/api/v1/twofactor/invalidate?" + TENANT_IDENTIFIER, "{ \"token\": \"" + tfaToken + "\" }", "");
}
